const raw=$json.choices?.[0]?.message?.content ?? $json;
const out=typeof raw==='string'?JSON.parse(raw):raw;
const allowed=new Set(['name','age','city','district','height_cm','weight_kg','breast_size','description']);
const fields={}; for(const [k,v] of Object.entries(out.fields||{})){if(allowed.has(k)&&v!==null&&v!=='') fields[k]=v;}
if(fields.age!==undefined&&(Number(fields.age)<18||Number(fields.age)>100)) throw new Error('Invalid age');
if(fields.height_cm!==undefined&&(Number(fields.height_cm)<100||Number(fields.height_cm)>250)) throw new Error('Invalid height');
if(fields.weight_kg!==undefined&&(Number(fields.weight_kg)<30||Number(fields.weight_kg)>300)) throw new Error('Invalid weight');
if(fields.breast_size!==undefined&&(Number(fields.breast_size)<0||Number(fields.breast_size)>20)) throw new Error('Invalid breast size');
const prices=(Array.isArray(out.prices)?out.prices:[]).map((p)=>{const amount=Number(p.amount);if(!String(p.service_name||'').trim()||!Number.isFinite(amount)||amount<0) throw new Error('Invalid price');const currency=String(p.currency||'RUB').toUpperCase();if(!/^[A-Z]{3}$/.test(currency)) throw new Error('Invalid currency');return {service_name:String(p.service_name).trim(),amount,currency,duration_minutes:p.duration_minutes==null?null:Number(p.duration_minutes),description:p.description==null?null:String(p.description)};});
const placeTypes=new Set(['HER_PLACE','HIS_PLACE','HOTEL','PUBLIC_PLACE','OTHER']);const meeting_places=(Array.isArray(out.meeting_places)?out.meeting_places:[]).map((p)=>{const type=String(p.place_type||'').toUpperCase(),label=String(p.label||'').trim();if(!placeTypes.has(type)||!label) throw new Error('Invalid meeting place');return {place_type:type,label,district:p.district==null?null:String(p.district),description:p.description==null?null:String(p.description)};});
return [{json:{payload_json:JSON.stringify({fields,prices,meeting_places,clarification:out.clarification||null}),session_id:$('Load WOMAN Draft Session').item.json.session_id,profile_id:$('Load WOMAN Draft Session').item.json.profile_id}}];
